def overlap_hours(a_start, a_end, b_start, b_end):
    """两个闭区间小时段的重叠小时数（含首尾），无重叠返回 0。输入为整数小时。"""
    start = max(a_start, b_start)
    end = min(a_end, b_end)
    if end < start:
        return 0
    return end - start

